        await commitIfShadow(ctx.shadow, `task: complete ${params.ref}`);

        pubsub.broadcast('tasks:updates', 'task_updated', {
          ref: params.ref,
          ulid: task._ulid,
          action: 'complete',
          status: 'completed',
        }, projectContext.path);

